#!/usr/bin/env bun
/**
 * Renders hub files from their fragments: TODOS.md from todos.d/.
 *
 *   bun scripts/fold-hub-fragments.ts                 write every generated file whose fragments changed
 *   bun scripts/fold-hub-fragments.ts --check         exit 1 unless every generated file matches its fragments
 *   bun scripts/fold-hub-fragments.ts --check --base <rev>
 *                                                     also pass a file that is still as <rev> left it
 *                                                     (fragments added or deleted, fold pending at land)
 *
 * --root <dir> runs against another checkout. The output is a pure function of the fragment files,
 * so a second run writes nothing. internal-task runs the fold in its housekeeping commits; it moves to land, as the ship
 * policy's release_tool, once gstack's tree receipt accepts a release_tool output.
 */
import { existsSync, lstatSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { spawnSync } from 'node:child_process';

export type Fragments = Map<string, string>;
export interface Target { output: string; dir: string; render: (files: Fragments) => string }
export interface TodoItem { name: string; section: string; body: string }

export const TODOS_HEADER = '> Generated by `scripts/fold-hub-fragments.ts` from [todos.d/](todos.d/README.md). Do not edit this file: to add, change or close an item, add, edit or delete its file in `todos.d/`.';
export const TODOS_PREAMBLE = '_preamble.md';
const NOT_ITEMS = new Set(['README.md', TODOS_PREAMBLE]);

export class FragmentError extends Error {}

export function parseTodo(name: string, text: string): TodoItem {
  const m = text.match(/^---\nsection: (.+)\n---\n([\s\S]*)$/);
  if (!m) throw new FragmentError(`todos.d/${name}: expected front matter "---", "section: <heading>", "---", then the item`);
  const section = m[1]!, body = m[2]!;
  if (section !== section.trim() || section.startsWith('#')) throw new FragmentError(`todos.d/${name}: section is the heading text without "## " and without surrounding spaces`);
  if (!/^- \[[ x]\] \S/.test(body)) throw new FragmentError(`todos.d/${name}: the item must start with "- [ ] " or "- [x] "`);
  if (body.indexOf('\n') !== body.length - 1) throw new FragmentError(`todos.d/${name}: the item is one line ending in a newline`);
  return { name, section, body };
}

export function sectionDate(section: string): string {
  return section.match(/\d{4}-\d{2}-\d{2}/g)?.pop() ?? '';
}

export function renderTodos(files: Fragments): string {
  const preamble = files.get(TODOS_PREAMBLE);
  if (preamble === undefined) throw new FragmentError(`todos.d/${TODOS_PREAMBLE} is missing`);
  const sections = new Map<string, TodoItem[]>();
  for (const [name, text] of files) {
    if (NOT_ITEMS.has(name)) continue;
    const item = parseTodo(name, text);
    sections.set(item.section, [...(sections.get(item.section) ?? []), item]);
  }
  const order = [...sections.keys()].sort((a, b) => {
    const da = sectionDate(a), db = sectionDate(b);
    if (da !== db) return da === '' ? 1 : db === '' ? -1 : da < db ? 1 : -1;
    return a < b ? -1 : a > b ? 1 : 0;
  });
  const body = order.map((s) => `## ${s}\n\n` + sections.get(s)!.sort((a, b) => (a.name < b.name ? -1 : 1)).map((i) => i.body).join('')).join('\n');
  return `${TODOS_HEADER}\n\n${preamble.trimEnd()}\n\n${body}`;
}

export const TARGETS: Target[] = [{ output: 'TODOS.md', dir: 'todos.d', render: renderTodos }];

function refuseSymlink(root: string, rel: string): void {
  if (lstatSync(join(root, rel), { throwIfNoEntry: false })?.isSymbolicLink()) throw new FragmentError(`${rel}: a symlink; the fold reads and writes only regular files in the checkout`);
}

export function readFragmentsDir(root: string, dir: string): Fragments {
  const files: Fragments = new Map();
  const abs = join(root, dir);
  refuseSymlink(root, dir);
  if (!existsSync(abs)) return files;
  for (const name of readdirSync(abs).sort()) {
    if (name.startsWith('.')) continue;
    if (!name.endsWith('.md') || !lstatSync(join(abs, name)).isFile()) throw new FragmentError(`${dir}/${name}: only regular .md fragment files belong here`);
    files.set(name, readFileSync(join(abs, name), 'utf8'));
  }
  return files;
}

function git(root: string, args: string[]): string | null {
  const r = spawnSync('git', args, { cwd: root, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 });
  return r.status === 0 ? r.stdout : null;
}

export function readFragmentsAt(root: string, rev: string, dir: string): Fragments | null {
  const list = git(root, ['ls-tree', '--name-only', `${rev}:${dir}`]);
  if (list === null) return null;
  const files: Fragments = new Map();
  for (const name of list.split('\n').filter(Boolean).sort()) {
    const text = git(root, ['show', `${rev}:${dir}/${name}`]);
    if (text !== null && name.endsWith('.md') && !name.startsWith('.')) files.set(name, text);
  }
  return files;
}

export function fold(root: string, targets = TARGETS): string[] {
  const lines: string[] = [];
  for (const t of targets) {
    const want = t.render(readFragmentsDir(root, t.dir));
    refuseSymlink(root, t.output);
    const path = join(root, t.output);
    if (existsSync(path) && readFileSync(path, 'utf8') === want) { lines.push(`fold: ${t.output} unchanged`); continue; }
    writeFileSync(path, want);
    lines.push(`fold: ${t.output} written from ${t.dir}/`);
  }
  return lines;
}

export function check(root: string, base: string | null, targets = TARGETS): { ok: boolean; lines: string[] } {
  const lines: string[] = [];
  let ok = true;
  const baseCommit = base ? git(root, ['rev-parse', '--verify', '--quiet', `${base}^{commit}`])?.trim() || null : null;
  const forkPoint = baseCommit ? git(root, ['merge-base', baseCommit, 'HEAD'])?.trim() || null : null;
  for (const t of targets) {
    refuseSymlink(root, t.output);
    const path = join(root, t.output);
    const have = existsSync(path) ? readFileSync(path, 'utf8') : null;
    if (have === t.render(readFragmentsDir(root, t.dir))) { lines.push(`check: ${t.output} matches ${t.dir}/`); continue; }
    if (baseCommit && have !== null && git(root, ['show', `${baseCommit}:${t.output}`]) === have) {
      lines.push(`check: ${t.output} pending (unchanged since ${baseCommit.slice(0, 12)}; internal-task's housekeeping fold writes it from ${t.dir}/)`);
      continue;
    }
    const atFork = forkPoint ? readFragmentsAt(root, forkPoint, t.dir) : null;
    if (atFork && have !== null && renderOrNull(t, atFork) === have) {
      lines.push(`check: ${t.output} pending (folded at ${forkPoint!.slice(0, 12)}; internal-task's housekeeping fold writes it from ${t.dir}/)`);
      continue;
    }
    ok = false;
    lines.push(`check: ${t.output} does not match ${t.dir}/ (change files in ${t.dir}/ only and leave ${t.output} as the base has it: git checkout <base> -- ${t.output})`);
  }
  return { ok, lines };
}

function renderOrNull(t: Target, files: Fragments): string | null {
  try { return t.render(files); } catch { return null; }
}

if (import.meta.main) {
  const args = process.argv.slice(2);
  const opt = (flag: string) => { const i = args.indexOf(flag); return i >= 0 ? args[i + 1] ?? null : null; };
  const root = resolve(opt('--root') ?? join(import.meta.dir, '..'));
  try {
    if (args.includes('--check')) {
      const r = check(root, opt('--base'));
      console.log(r.lines.join('\n'));
      process.exit(r.ok ? 0 : 1);
    }
    console.log(fold(root).join('\n'));
  } catch (e) {
    if (!(e instanceof FragmentError)) throw e;
    console.error(`fold-hub-fragments: ${e.message}`);
    process.exit(1);
  }
}
